function estateDocument(PDO $pdo,int $admin,string $name,string $bytes,int $building=0,int $lease=0):int {
 if(strlen($bytes)<1||strlen($bytes)>10*1024*1024)throw new InvalidArgumentException('Originaldatei1 Byte bis10MB.');$name=gszName($name);$extension=strtolower(pathinfo($name,PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->buffer($bytes);$types=['pdf'=>['application/pdf'],'jpg'=>['image/jpeg'],'jpeg'=>['image/jpeg'],'png'=>['image/png'],'txt'=>['text/plain'],'csv'=>['text/plain','text/csv','application/csv']];if(!isset($types[$extension])||!in_array($mime,$types[$extension],true))throw new InvalidArgumentException('Originalformat PDF/JPEG/PNG/UTF-8-Text/CSV erforderlich.');if(in_array($extension,['txt','csv'],true)&&(!mb_check_encoding($bytes,'UTF-8')||str_contains($bytes,"\0")))throw new InvalidArgumentException('Textdatei benötigt UTF-8 ohne Nullbytes.');if(in_array($extension,['jpg','jpeg','png'],true)){$image=@getimagesizefromstring($bytes);if(!$image||$image[0]*$image[1]>40000000)throw new InvalidArgumentException('Bilddaten/Größe ungültig.');}
 return estateTx($pdo,$admin,function()use($pdo,$admin,$name,$bytes,$mime,$building,$lease){if($building)estateLock($pdo,'estate_buildings',$building);if($lease){$l=estateLock($pdo,'estate_leases',$lease);$u=estateLock($pdo,'estate_units',(int)$l['unit_id']);if($building&&(int)$u['building_id']!==$building)throw new RuntimeException('Vertrag gehört zu anderem Gebäude.');}$file=gszStoreBytes('estate',$bytes);$q=$pdo->prepare('SELECT id FROM estate_documents WHERE sha256=? AND building_id<=>? AND lease_id<=>? LIMIT 1');$q->execute([$file['sha256'],$building?:null,$lease?:null]);if($id=$q->fetchColumn())return (int)$id;$pdo->prepare('INSERT INTO estate_documents(building_id,lease_id,original_name,mime_type,sha256,size_bytes,created_by) VALUES(?,?,?,?,?,?,?)')->execute([$building?:null,$lease?:null,$name,$mime,$file['sha256'],$file['size_bytes'],$admin]);$id=(int)$pdo->lastInsertId();estateEvent($pdo,$admin,'document',$id,'original_archived',[],['sha256'=>$file['sha256'],'size_bytes'=>$file['size_bytes']]);return $id;});
}
function estateExpense(PDO $pdo,int $admin,int $transaction,int $building,int $unit,string $category,int $document,string $notes):int {
 $category=opsText(['category'=>$category],'category',190,true);$notes=opsText(['notes'=>$notes],'notes',5000);return estateTx($pdo,$admin,function()use($pdo,$admin,$transaction,$building,$unit,$category,$document,$notes){$t=estateLock($pdo,'estate_bank_transactions',$transaction);if((int)$t['amount_cents']>=0)throw new RuntimeException('Ausgabe benötigt negativen Immobilienumsatz.');estateLock($pdo,'estate_buildings',$building);if($unit){$u=estateLock($pdo,'estate_units',$unit);if((int)$u['building_id']!==$building)throw new RuntimeException('Einheit gehört zu anderem Gebäude.');}if($document){$d=estateLock($pdo,'estate_documents',$document);if($d['building_id']&&(int)$d['building_id']!==$building)throw new RuntimeException('Beleg gehört zu anderem Gebäude.');gszReadBytes('estate',$d['sha256'],$d['sha256']);}$q=$pdo->prepare('SELECT id FROM estate_payments WHERE bank_transaction_id=? UNION ALL SELECT id FROM estate_transfers WHERE outgoing_id=? OR incoming_id=?');$q->execute([$transaction,$transaction,$transaction]);if($q->fetch())throw new RuntimeException('Umsatz bereits als Zahlung/Umbuchung zugeordnet.');$q=$pdo->prepare('SELECT * FROM estate_expenses WHERE transaction_id=?');$q->execute([$transaction]);if($old=$q->fetch()){if((int)$old['building_id']===$building&&(int)$old['unit_id']===$unit&&$old['category']===$category&&(int)$old['document_id']===$document&&$old['notes']===$notes)return (int)$old['id'];throw new RuntimeException('Bestehende Ausgabenzuordnung nicht still ersetzen. Korrektur separat prüfen.');}$pdo->prepare('INSERT INTO estate_expenses(transaction_id,building_id,unit_id,category,notes,document_id,created_by) VALUES(?,?,?,?,?,?,?)')->execute([$transaction,$building,$unit?:null,$category,$notes,$document?:null,$admin]);$id=(int)$pdo->lastInsertId();estateEvent($pdo,$admin,'expense',$id,'expense_assigned',[],['transaction_id'=>$transaction,'building_id'=>$building,'category'=>$category,'document_id'=>$document?:null,'apportionable'=>'not_decided']);return $id;});
}
